import XCTest
@testable import HRCore
#if canImport(CryptoKit)
import CryptoKit
#endif

/// Loads the cross-language vectors generated by `go run ./proto/cmd/genvectors`.
enum Vectors {
    struct TBSVector: Decodable {
        var label: String
        var fieldsB64: [String]
        var tbsHex: String
        var signer: String
        var sig: String
    }

    /// Adding another Mac (PROTOCOL.md §10).
    struct Join: Decodable {
        var macId: String
        var t: String
        var code: String
    }

    struct File: Decodable {
        var hostSeedHex: String
        var hostPub: String
        var deviceSeedHex: String
        var devicePub: String
        var hostFingerprint: String
        var tbs: [TBSVector]
        var sas: String
        var join: Join?
        var inputs: [String: String]
    }

    static func load() throws -> File {
        // Tests/HRCoreTests/<file> → repo root is four levels up.
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let url = root.appendingPathComponent("testdata/vectors.json")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("testdata/vectors.json not found at \(url.path)")
        }
        return try JSONDecoder().decode(File.self, from: Data(contentsOf: url))
    }

    static func hex(_ s: String) -> Data {
        var out = Data()
        var index = s.startIndex
        while index < s.endIndex {
            let next = s.index(index, offsetBy: 2)
            out.append(UInt8(s[index..<next], radix: 16)!)
            index = next
        }
        return out
    }
}

final class EncodingTests: XCTestCase {
    func testSASFormatting() {
        XCTAssertEqual(SASFormatter.format("123456"), "123 456")
        XCTAssertEqual(SASFormatter.format("196924"), "196 924")
        XCTAssertEqual(SASFormatter.format("123 456"), "123 456")
        XCTAssertEqual(SASFormatter.format("12345"), "12345")
        XCTAssertEqual(SASFormatter.format("12a456"), "12a456")
        XCTAssertEqual(SASFormatter.format(""), "")
        XCTAssertNil(SASFormatter.groups("１２３４５６"))   // full-width digits are not accepted
        XCTAssertEqual(SASFormatter.groups("000042")?.0, "000")
        XCTAssertEqual(SASFormatter.groups("000042")?.1, "042")
        XCTAssertEqual(SASFormatter.zeroPadded(42), "000042")
        XCTAssertEqual(SASFormatter.zeroPadded(999_999), "999999")
        XCTAssertEqual(SASFormatter.zeroPadded(1_000_000), "000000")
    }

    func testSASFromDigest() {
        // 0x000F4240 = 1_000_000 → 0; 0xFFFFFFFF = 4294967295 → 967295
        XCTAssertEqual(SASFormatter.code(fromDigest: [0x00, 0x0F, 0x42, 0x40, 9, 9]), "000000")
        XCTAssertEqual(SASFormatter.code(fromDigest: [0xFF, 0xFF, 0xFF, 0xFF]), "967295")
        XCTAssertNil(SASFormatter.code(fromDigest: [1, 2, 3]))
    }

    func testFingerprintFormatFromKnownDigest() {
        // SHA-256(vector hostPub)[0:10] = 65b60673d6ed884bf01c → "mw3a-m46w-5wee-x4a4"
        let digest: [UInt8] = [0x65, 0xb6, 0x06, 0x73, 0xd6, 0xed, 0x88, 0x4b, 0xf0, 0x1c, 0xAA, 0xBB]
        XCTAssertEqual(Fingerprint.format(sha256Digest: digest), "mw3a-m46w-5wee-x4a4")
    }

    func testBase32() {
        // RFC 4648 test vectors (lowercased, unpadded)
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("".utf8)), "")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("f".utf8)), "my")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("fo".utf8)), "mzxq")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("foo".utf8)), "mzxw6")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("foob".utf8)), "mzxw6yq")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("fooba".utf8)), "mzxw6ytb")
        XCTAssertEqual(Base32.encodeLowercaseNoPadding(Array("foobar".utf8)), "mzxw6ytboi")
    }

    func testBase64URL() {
        let bytes = Data([0xfb, 0xff, 0xfe, 0x00, 0x01])
        XCTAssertEqual(Base64URL.encode(bytes), "-__-AAE")
        XCTAssertEqual(Base64URL.decode("-__-AAE"), bytes)
        XCTAssertEqual(Base64URL.decode("-__-AAE="), bytes)
        XCTAssertNil(Base64URL.decode("+//+AAE"))
        XCTAssertNil(Base64URL.decode("a"))
        XCTAssertNil(Base64URL.decode("!!!!"))
        XCTAssertEqual(Base64URL.decode(""), Data())
        let random = Data((0..<97).map { UInt8(($0 * 37) & 0xFF) })
        XCTAssertEqual(Base64URL.decode(Base64URL.encode(random)), random)
    }

    func testTBSMatchesGoVectors() throws {
        let v = try Vectors.load()
        XCTAssertFalse(v.tbs.isEmpty)
        for vector in v.tbs {
            let fields = try vector.fieldsB64.map { try XCTUnwrap(Base64URL.decode($0), vector.label) }
            let tbs = TBS.build(label: vector.label, fields: fields)
            XCTAssertEqual(tbs, Vectors.hex(vector.tbsHex), vector.label)
            let parsed = try XCTUnwrap(TBS.parse(tbs))
            XCTAssertEqual(parsed.label, vector.label)
            XCTAssertEqual(parsed.fields, fields)
            XCTAssertEqual(TBS.label(of: tbs), vector.label)
        }
    }

    func testSigningPolicyMatchesProtocolSigners() throws {
        let v = try Vectors.load()
        for vector in v.tbs {
            let tbs = Vectors.hex(vector.tbsHex)
            XCTAssertEqual(SigningPolicy.isAllowed(tbs), vector.signer == "host",
                           "\(vector.label) signed by \(vector.signer)")
        }
        // The host also signs certs and revocations (not in the TBS vector list).
        XCTAssertTrue(SigningPolicy.isAllowed(TBS.build(label: "HR1/cert", fields: [Data([1]), Data([2]), Data(), Data(), Data("1".utf8)])))
        XCTAssertTrue(SigningPolicy.isAllowed(TBS.build(label: "HR1/revoked", fields: [Data([1])])))
        // Malformed or foreign transcripts are refused.
        XCTAssertFalse(SigningPolicy.isAllowed(Data()))
        XCTAssertFalse(SigningPolicy.isAllowed(Data("HR1/cert".utf8)))
        XCTAssertFalse(SigningPolicy.isAllowed(Data("HR1/cert".utf8) + Data([0, 0, 0, 0, 9])))
        XCTAssertFalse(SigningPolicy.isAllowed(TBS.build(label: "HR1/sas", fields: [])))
        XCTAssertFalse(SigningPolicy.isAllowed(TBS.build(label: "HR1/kill-request", fields: [])))
        XCTAssertFalse(SigningPolicy.isAllowed(Data("arbitrary bytes".utf8)))
    }

    #if canImport(CryptoKit)
    func testHostKeyFromSeedAndSignaturesWithCryptoKit() throws {
        let v = try Vectors.load()
        let hostKey = try Curve25519.Signing.PrivateKey(rawRepresentation: Vectors.hex(v.hostSeedHex))
        XCTAssertEqual(Base64URL.encode(hostKey.publicKey.rawRepresentation), v.hostPub)
        let deviceKey = try Curve25519.Signing.PrivateKey(rawRepresentation: Vectors.hex(v.deviceSeedHex))
        XCTAssertEqual(Base64URL.encode(deviceKey.publicKey.rawRepresentation), v.devicePub)

        // Fingerprint of the host key.
        let digest = Array(SHA256.hash(data: hostKey.publicKey.rawRepresentation))
        XCTAssertEqual(Fingerprint.format(sha256Digest: digest), v.hostFingerprint)

        for vector in v.tbs {
            let tbs = Vectors.hex(vector.tbsHex)
            let sig = try XCTUnwrap(Base64URL.decode(vector.sig))
            let pub = vector.signer == "host" ? hostKey.publicKey : deviceKey.publicKey
            XCTAssertTrue(pub.isValidSignature(sig, for: tbs), vector.label)
            if vector.signer == "host" {
                // CryptoKit signatures are randomised, so compare by verification.
                let ours = try hostKey.signature(for: tbs)
                XCTAssertTrue(hostKey.publicKey.isValidSignature(ours, for: tbs))
            }
        }
    }

    func testSASVectorWithCryptoKit() throws {
        let v = try Vectors.load()
        let hostPub = try XCTUnwrap(Base64URL.decode(v.hostPub))
        let devicePub = try XCTUnwrap(Base64URL.decode(v.devicePub))
        let nd = try XCTUnwrap(Base64URL.decode(try XCTUnwrap(v.inputs["nd"])))
        let na = try XCTUnwrap(Base64URL.decode(try XCTUnwrap(v.inputs["na"])))
        let tbs = TBS.build(label: "HR1/sas", fields: [hostPub, devicePub, nd, na])
        let digest = Array(SHA256.hash(data: tbs))
        XCTAssertEqual(SASFormatter.code(fromDigest: digest), v.sas)
    }
    #endif
}
